CREATE OR REPLACE FUNCTION public._saldo_de(p_user uuid)
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(sum(monto), 0)::bigint from public.movimientos_billetera where user_id = p_user;
$function$
CREATE OR REPLACE FUNCTION public.es_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select exists (select 1 from public.profiles where id = auth.uid() and rol = 'admin');
$function$
CREATE OR REPLACE FUNCTION public.mi_saldo()
 RETURNS bigint
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select coalesce(sum(monto), 0)::bigint from public.movimientos_billetera where user_id = auth.uid();
$function$
CREATE OR REPLACE FUNCTION public.actualizar_nick(p_nick text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'No autenticado'; end if;
  if p_nick is null or char_length(trim(p_nick)) not between 3 and 20 then
    raise exception 'El nick debe tener entre 3 y 20 caracteres';
  end if;
  update public.profiles set nick = trim(p_nick) where id = auth.uid();
exception when unique_violation then
  raise exception 'Ese nick ya está en uso';
end $function$
CREATE OR REPLACE FUNCTION public.crear_recarga(p_monto bigint, p_numero_operacion text, p_captura_path text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_id  uuid;
begin
  if v_uid is null then raise exception 'No autenticado'; end if;
  if exists (select 1 from profiles where id = v_uid and baneado) then
    raise exception 'Cuenta baneada';
  end if;
  if p_monto is null or p_monto < 100 then raise exception 'Monto mínimo: S/ 1.00'; end if;
  if p_monto > 50000 then raise exception 'Monto máximo por recarga: S/ 500.00'; end if;
  if p_numero_operacion is null or char_length(trim(p_numero_operacion)) < 4 then
    raise exception 'Número de operación inválido';
  end if;

  insert into recargas (user_id, monto, numero_operacion, captura_path)
  values (v_uid, p_monto, trim(p_numero_operacion), p_captura_path)
  returning id into v_id;
  return v_id;
exception when unique_violation then
  raise exception 'Ese número de operación ya fue registrado';
end $function$
CREATE OR REPLACE FUNCTION public.aprobar_recarga(p_recarga uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r recargas%rowtype;
begin
  if not es_admin() then raise exception 'Solo administradores'; end if;
  select * into r from recargas where id = p_recarga for update;
  if not found then raise exception 'La recarga no existe'; end if;
  if r.estado <> 'pendiente' then raise exception 'La recarga ya fue procesada'; end if;

  insert into movimientos_billetera (user_id, tipo, monto, referencia_id, descripcion, creado_por)
  values (r.user_id, 'recarga', r.monto, r.id, 'Recarga Yape/Plin, operación ' || r.numero_operacion, auth.uid());

  update recargas
     set estado = 'aprobada', revisado_por = auth.uid(), revisado_en = now()
   where id = r.id;
end $function$
CREATE OR REPLACE FUNCTION public.rechazar_recarga(p_recarga uuid, p_nota text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not es_admin() then raise exception 'Solo administradores'; end if;
  update recargas
     set estado = 'rechazada', nota_admin = p_nota, revisado_por = auth.uid(), revisado_en = now()
   where id = p_recarga and estado = 'pendiente';
  if not found then raise exception 'La recarga no existe o ya fue procesada'; end if;
end $function$
CREATE OR REPLACE FUNCTION public.solicitar_retiro(p_monto bigint, p_destino text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_id  uuid;
begin
  if v_uid is null then raise exception 'No autenticado'; end if;
  -- Bloquea la fila del jugador: evita dos retiros/entradas simultáneos que gasten el mismo saldo
  perform 1 from profiles where id = v_uid and not baneado for no key update;
  if not found then raise exception 'Cuenta no disponible'; end if;

  if p_monto is null or p_monto < 500 then raise exception 'Retiro mínimo: S/ 5.00'; end if;
  if p_destino is null or char_length(trim(p_destino)) < 6 then raise exception 'Destino inválido'; end if;
  if _saldo_de(v_uid) < p_monto then raise exception 'Saldo insuficiente'; end if;

  insert into retiros (user_id, monto, destino) values (v_uid, p_monto, trim(p_destino))
  returning id into v_id;

  insert into movimientos_billetera (user_id, tipo, monto, referencia_id, descripcion)
  values (v_uid, 'retiro', -p_monto, v_id, 'Solicitud de retiro');
  return v_id;
end $function$
CREATE OR REPLACE FUNCTION public.marcar_retiro_pagado(p_retiro uuid, p_nota text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not es_admin() then raise exception 'Solo administradores'; end if;
  update retiros
     set estado = 'pagado', nota_admin = p_nota, procesado_por = auth.uid(), procesado_en = now()
   where id = p_retiro and estado = 'solicitado';
  if not found then raise exception 'El retiro no existe o ya fue procesado'; end if;
end $function$
CREATE OR REPLACE FUNCTION public.rechazar_retiro(p_retiro uuid, p_nota text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r retiros%rowtype;
begin
  if not es_admin() then raise exception 'Solo administradores'; end if;
  update retiros
     set estado = 'rechazado', nota_admin = p_nota, procesado_por = auth.uid(), procesado_en = now()
   where id = p_retiro and estado = 'solicitado'
