  values (r.user_id, 'reembolso', r.monto, r.id, 'Retiro rechazado: devolución', auth.uid());
end $function$
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.profiles (id, nick)
  values (
    new.id,
    coalesce(nullif(trim(new.raw_user_meta_data->>'nick'), ''), 'jugador_' || substr(new.id::text, 1, 8))
  );
  return new;
end $function$
