CREATE OR REPLACE FUNCTION public.cerrar_partida(p_sala uuid, p_dota_match_id bigint, p_equipo_ganador smallint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s            salas%rowtype;
  v_total      int;
  v_sin_equipo int;
  v_ganadores  int;
  v_mitad      int;
  v_pozo       bigint;
  v_com        bigint;
  v_neto       bigint;
  v_premio     bigint;
  v_sobrante   bigint;
begin
  if not es_admin() then raise exception 'Solo administradores'; end if;
  if p_equipo_ganador not in (1, 2) then raise exception 'Equipo ganador inválido'; end if;

  select * into s from salas where id = p_sala for update;
  if not found then raise exception 'La sala no existe'; end if;
  if s.estado <> 'en_juego' then raise exception 'La sala debe estar en juego'; end if;

  select count(*),
         count(*) filter (where equipo is null),
         count(*) filter (where equipo = p_equipo_ganador)
    into v_total, v_sin_equipo, v_ganadores
    from participantes_sala where sala_id = p_sala;

  v_mitad := s.cupo / 2;
  if v_total <> s.cupo or v_sin_equipo > 0 then raise exception 'Faltan jugadores o hay equipos sin asignar'; end if;
  if v_ganadores <> v_mitad then raise exception 'Los equipos no están balanceados'; end if;

  v_pozo     := s.cuota * s.cupo;
  v_com      := (v_pozo * s.comision_bp) / 10000;
  v_neto     := v_pozo - v_com;
  v_premio   := v_neto / v_mitad;
  v_sobrante := v_neto - v_premio * v_mitad;     -- céntimos que sobran por redondeo: van a la casa

  insert into movimientos_billetera (user_id, tipo, monto, referencia_id, descripcion, creado_por)
  select user_id, 'premio', v_premio, s.id, 'Premio sala ' || s.nombre, auth.uid()
    from participantes_sala
   where sala_id = p_sala and equipo = p_equipo_ganador;

  insert into partidas (sala_id, dota_match_id, equipo_ganador, pozo, comision, premio_por_ganador, cerrada_por)
  values (s.id, p_dota_match_id, p_equipo_ganador, v_pozo, v_com + v_sobrante, v_premio, auth.uid());

  update salas set estado = 'terminada' where id = s.id;
exception when unique_violation then
  raise exception 'Ese ID de partida de Dota ya fue usado en otra sala';
end $function$
CREATE OR REPLACE FUNCTION public.cancelar_sala(p_sala uuid, p_motivo text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s salas%rowtype;
begin
  if not es_admin() then raise exception 'Solo administradores'; end if;
  select * into s from salas where id = p_sala for update;
  if not found then raise exception 'La sala no existe'; end if;
  if s.estado not in ('abierta', 'llena', 'en_juego') then
    raise exception 'Esta sala ya no se puede cancelar';
  end if;

  insert into movimientos_billetera (user_id, tipo, monto, referencia_id, descripcion, creado_por)
  select user_id, 'reembolso', s.cuota, s.id,
         'Sala cancelada: ' || coalesce(p_motivo, 'sin motivo'), auth.uid()
    from participantes_sala where sala_id = p_sala;

  update salas set estado = 'cancelada' where id = p_sala;
end $function$
CREATE OR REPLACE FUNCTION public.crear_sala(p_nombre text, p_cuota bigint, p_cupo integer DEFAULT 10, p_comision_bp integer DEFAULT 1500)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id uuid;
  v_modalidad text;
begin
  if not es_admin() then raise exception 'Solo administradores'; end if;
  if p_nombre is null or trim(p_nombre) = '' then
    raise exception 'Escribe un nombre para la sala';
  end if;
  if p_cuota is null or p_cuota <= 0 then
    raise exception 'Cuota inválida';
  end if;
  if p_cupo not in (2, 10) then
    raise exception 'Cupo inválido: usa 2 (1v1) o 10 (5v5)';
  end if;

  v_modalidad := case when p_cupo = 2 then '1v1' else '5v5' end;

  insert into salas (nombre, cuota, cupo, comision_bp, modalidad, creado_por)
  values (trim(p_nombre), p_cuota, p_cupo, coalesce(p_comision_bp, 1500), v_modalidad, auth.uid())
  returning id into v_id;

  return v_id;
end
$function$
CREATE OR REPLACE FUNCTION public.asignar_equipo(p_sala uuid, p_user uuid, p_equipo smallint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s salas%rowtype;
  v_count int;
begin
  if not es_admin() then raise exception 'Solo administradores'; end if;
  if p_equipo is not null and p_equipo not in (1, 2) then
    raise exception 'Equipo inválido';
  end if;

  select * into s from salas where id = p_sala for update;
  if not found then raise exception 'La sala no existe'; end if;
  if s.estado not in ('abierta', 'llena') then
    raise exception 'La sala no acepta cambios';
  end if;

  if p_equipo is not null then
    select count(*) into v_count
      from participantes_sala
     where sala_id = p_sala and equipo = p_equipo and user_id <> p_user;

    if v_count >= s.cupo / 2 then
      raise exception 'Ese equipo está lleno';
    end if;
  end if;

  update participantes_sala set equipo = p_equipo
   where sala_id = p_sala and user_id = p_user;

  if not found then
    raise exception 'Ese jugador no está en la sala';
  end if;
end
$function$
CREATE OR REPLACE FUNCTION public.ganancias_casa()
 RETURNS bigint
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not es_admin() then raise exception 'Solo administradores'; end if;
  return (select coalesce(sum(comision), 0)::bigint from partidas);
end $function$
CREATE OR REPLACE FUNCTION public.unirse_a_equipo(p_sala uuid, p_equipo smallint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  s salas%rowtype;
  v_count int;
begin
  if v_uid is null then raise exception 'No autenticado'; end if;
  if p_equipo is not null and p_equipo not in (1, 2) then
    raise exception 'Equipo inválido';
  end if;

  select * into s from salas where id = p_sala for update;
  if not found then raise exception 'La sala no existe'; end if;
  if s.estado not in ('abierta', 'llena') then
    raise exception 'La sala no acepta cambios';
  end if;

  if not exists (
    select 1 from participantes_sala where sala_id = p_sala and user_id = v_uid
  ) then
    raise exception 'No estás en esta sala';
  end if;

  if p_equipo is not null then
    select count(*) into v_count
      from participantes_sala
     where sala_id = p_sala and equipo = p_equipo and user_id <> v_uid;

    if v_count >= s.cupo / 2 then
      raise exception 'Ese equipo está lleno';
    end if;
  end if;

  update participantes_sala set equipo = p_equipo
   where sala_id = p_sala and user_id = v_uid;
end
$function$
CREATE OR REPLACE FUNCTION public.ajuste_admin(p_user uuid, p_monto bigint, p_motivo text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not es_admin() then raise exception 'Solo administradores'; end if;
  if p_monto is null or p_monto = 0 then raise exception 'Monto inválido'; end if;
  if p_motivo is null or char_length(trim(p_motivo)) < 5 then raise exception 'Escribe el motivo del ajuste'; end if;

  perform 1 from profiles where id = p_user for no key update;
  if not found then raise exception 'El usuario no existe'; end if;
  if p_monto < 0 and _saldo_de(p_user) + p_monto < 0 then
    raise exception 'El ajuste dejaría el saldo en negativo';
  end if;

  insert into movimientos_billetera (user_id, tipo, monto, descripcion, creado_por)
  values (p_user, 'ajuste_admin', p_monto, trim(p_motivo), auth.uid());
end $function$
CREATE OR REPLACE FUNCTION public.verificar_saldo_no_negativo()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_saldo bigint;
begin
  if new.monto >= 0 then return new; end if;  -- ingresos no necesitan verificación
  perform 1 from public.profiles where id = new.user_id for no key update;  -- evita carreras
  select coalesce(sum(monto), 0) into v_saldo
    from public.movimientos_billetera where user_id = new.user_id;
  if v_saldo + new.monto < 0 then
    raise exception 'Saldo insuficiente';
  end if;
  return new;
end $function$
CREATE OR REPLACE FUNCTION public.unirse_a_sala(p_sala uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  s     salas%rowtype;
  v_n   int;
begin
  if v_uid is null then raise exception 'No autenticado'; end if;
  perform 1 from profiles where id = v_uid and not baneado for no key update;
  if not found then raise exception 'Cuenta no disponible'; end if;

  perform 1 from profiles where id = v_uid and steam_id is not null;
  if not found then raise exception 'Debes vincular tu cuenta de Steam primero'; end if;

  if exists (
    select 1 from participantes_sala ps
    join salas s2 on s2.id = ps.sala_id
    where ps.user_id = v_uid and s2.estado in ('abierta', 'llena', 'en_juego')
  ) then
    raise exception 'Ya estás en otra sala. Sal de ella primero.';
  end if;

  select * into s from salas where id = p_sala for update;
  if not found then raise exception 'La sala no existe'; end if;
  if s.estado <> 'abierta' then raise exception 'La sala no está abierta'; end if;
  if exists (select 1 from participantes_sala where sala_id = p_sala and user_id = v_uid) then
    raise exception 'Ya estás en esta sala';
  end if;

  select count(*) into v_n from participantes_sala where sala_id = p_sala;
  if v_n >= s.cupo then raise exception 'La sala está llena'; end if;
  if _saldo_de(v_uid) < s.cuota then raise exception 'Saldo insuficiente'; end if;

  insert into movimientos_billetera (user_id, tipo, monto, referencia_id, descripcion)
  values (v_uid, 'entrada_sala', -s.cuota, s.id, 'Entrada a sala ' || s.nombre);
  insert into participantes_sala (sala_id, user_id) values (p_sala, v_uid);

  if v_n + 1 >= s.cupo then
    update salas set estado = 'llena' where id = p_sala;
  end if;
end $function$
CREATE OR REPLACE FUNCTION public.definir_lobby(p_sala uuid, p_nombre text, p_clave text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s salas%rowtype;
  v_total int;
  v_sin int;
  v_radiant int;
  v_dire int;
begin
  if not es_admin() then raise exception 'Solo administradores'; end if;
  if p_nombre is null or trim(p_nombre) = '' then
    raise exception 'Escribe el nombre del lobby';
  end if;
  if p_clave is null or trim(p_clave) = '' then
    raise exception 'Escribe la clave del lobby';
  end if;

  select * into s from salas where id = p_sala for update;
  if not found then raise exception 'La sala no existe'; end if;
  if s.estado not in ('llena', 'en_juego') then
    raise exception 'La sala debe estar llena';
  end if;

  select count(*),
         count(*) filter (where equipo is null),
         count(*) filter (where equipo = 1),
         count(*) filter (where equipo = 2)
    into v_total, v_sin, v_radiant, v_dire
    from participantes_sala
   where sala_id = p_sala;

  if v_total <> s.cupo then
    raise exception 'Faltan jugadores para iniciar';
  end if;
  if v_sin > 0 then
    raise exception 'Hay jugadores en lista de espera';
  end if;
  if v_radiant <> s.cupo / 2 or v_dire <> s.cupo / 2 then
    raise exception 'Los equipos no están balanceados';
  end if;

  insert into lobbies (sala_id, nombre, clave)
  values (p_sala, trim(p_nombre), trim(p_clave))
  on conflict (sala_id) do update
    set nombre = excluded.nombre, clave = excluded.clave;

  update salas set estado = 'en_juego' where id = p_sala;

  insert into notificaciones (user_id, tipo, mensaje)
  select user_id,
         'partida_iniciada',
         'La partida de "' || s.nombre || '" comenzó. Lobby: ' ||
         trim(p_nombre) || ' | Clave: ' || trim(p_clave)
    from participantes_sala
   where sala_id = p_sala;
end
$function$
CREATE OR REPLACE FUNCTION public.capitan_de_pick(p_primer uuid, p_otro uuid, p_num integer)
 RETURNS uuid
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_num is null or p_num < 1 or p_primer is null or p_otro is null then null
    when (((p_num - 1) / 2) % 2) = 0 then
      case when ((p_num - 1) % 2) = 0 then p_primer else p_otro end
    else
      case when ((p_num - 1) % 2) = 0 then p_otro else p_primer end
  end;
$function$
CREATE OR REPLACE FUNCTION public.expulsar_de_sala(p_sala uuid, p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s salas%rowtype;
begin
  if not es_admin() then raise exception 'Solo administradores'; end if;

  select * into s from salas where id = p_sala for update;
  if not found then raise exception 'La sala no existe'; end if;
  if s.estado not in ('abierta', 'llena') then
    raise exception 'No se puede expulsar en este estado';
  end if;

  delete from participantes_sala where sala_id = p_sala and user_id = p_user;
  if not found then raise exception 'Ese jugador no está en la sala'; end if;

  insert into movimientos_billetera (user_id, tipo, monto, referencia_id, descripcion, creado_por)
  values (p_user, 'reembolso', s.cuota, s.id, 'Expulsión de sala ' || s.nombre, auth.uid());

  if s.estado = 'llena' then
    update salas set estado = 'abierta' where id = p_sala;
  end if;

  insert into notificaciones (user_id, tipo, mensaje)
  values (p_user, 'expulsado_sala', 'El administrador te sacó de la sala "' || s.nombre || '". Se te devolvió la cuota.');
end
$function$
CREATE OR REPLACE FUNCTION public.cancelar_picks(p_sala uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s public.salas%rowtype;
begin
  if not public.es_admin() then raise exception 'Solo administradores'; end if;

  select * into s from public.salas where id = p_sala for update;
  if not found then raise exception 'La sala no existe'; end if;
  if s.estado = 'en_juego' then raise exception 'La partida ya está en juego'; end if;
  if s.picks_estado = 'inactivo' then return; end if;

  perform set_config('app.picks_operacion', 'on', true);

  update public.participantes_sala
  set equipo = null, es_capitan = false, pick_orden = null
  where sala_id = p_sala;

  update public.salas
  set picks_estado = 'inactivo',
      pick_capitan1 = null,
      pick_capitan2 = null,
      pick_ganador_moneda = null,
      pick_decision_user_id = null,
      pick_decision_tipo = null,
      pick_primer_user_id = null,
      pick_turno_user_id = null,
      pick_turno_expira_at = null
  where id = p_sala;
end;
$function$
CREATE OR REPLACE FUNCTION public.marcar_inicio_sala()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.estado = 'en_juego' and old.estado is distinct from 'en_juego' then
    new.iniciada_at := now();
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.cerrar_partida_con_detalle(p_sala uuid, p_dota_match_id bigint, p_equipo_ganador integer, p_duracion integer DEFAULT NULL::integer, p_radiant_score integer DEFAULT NULL::integer, p_dire_score integer DEFAULT NULL::integer, p_auto boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s public.salas%rowtype;
begin
  if not public.es_admin() then
    raise exception 'Solo administradores';
  end if;

  select * into s from public.salas where id = p_sala for update;
  if not found then raise exception 'La sala no existe'; end if;
  if s.estado <> 'en_juego' then raise exception 'La sala no está en juego'; end if;
  if p_dota_match_id is null or p_dota_match_id <= 0 then
    raise exception 'ID de partida inválido';
  end if;
  if p_equipo_ganador not in (1, 2) then
    raise exception 'Equipo ganador inválido';
  end if;

  perform public.cerrar_partida(p_sala, p_dota_match_id, p_equipo_ganador);

  update public.partidas
  set duracion_segundos = coalesce(p_duracion, duracion_segundos),
      radiant_score = coalesce(p_radiant_score, radiant_score),
      dire_score = coalesce(p_dire_score, dire_score),
      detectada_auto = coalesce(p_auto, false)
  where sala_id = p_sala and dota_match_id = p_dota_match_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.admin_destacar_sala(p_sala uuid, p_destacar boolean DEFAULT true)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then raise exception 'No autenticado'; end if;
  if not exists (
    select 1 from public.profiles
    where id = auth.uid() and rol = 'admin'
  ) then
    raise exception 'Solo un administrador puede elegir la sala destacada';
  end if;

  if p_destacar then
    if not exists (
      select 1 from public.salas
      where id = p_sala
        and estado in ('abierta', 'llena', 'en_juego')
    ) then
      raise exception 'Sala no encontrada o no está activa';
    end if;

    update public.salas
    set destacada = false
    where destacada = true and id <> p_sala;

    update public.salas
    set destacada = true
    where id = p_sala;
  else
    update public.salas
    set destacada = false
    where id = p_sala;
  end if;
end;
$function$
CREATE OR REPLACE FUNCTION public.notificar_usuario(p_user uuid, p_tipo text, p_mensaje text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.es_admin() then
    raise exception 'Solo administradores';
  end if;

  if p_user is null or p_tipo is null or p_mensaje is null then
    raise exception 'Datos incompletos';
  end if;

  if length(p_mensaje) > 500 then
    raise exception 'Mensaje demasiado largo';
  end if;

  if not exists (select 1 from public.profiles where id = p_user) then
    raise exception 'El usuario no existe';
  end if;

  insert into public.notificaciones (user_id, tipo, mensaje)
  values (p_user, p_tipo, p_mensaje);
end;
$function$
CREATE OR REPLACE FUNCTION public.marcar_notificaciones_leidas(p_ids uuid[] DEFAULT NULL::uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Debes iniciar sesión';
  end if;

  if p_ids is null then
    update public.notificaciones
    set leida = true
    where user_id = auth.uid() and leida = false;
  else
    update public.notificaciones
    set leida = true
    where user_id = auth.uid() and id = any(p_ids);
  end if;
end;
$function$
CREATE OR REPLACE FUNCTION public.confirmar_verificacion(p_sala uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_estado text;
  v_expira timestamptz;
  v_creado_por uuid;
  v_nombre text;
  v_socios int;
  v_listos int;
begin
  if v_uid is null then
    raise exception 'Debes iniciar sesión';
  end if;

  select s.verificacion_estado, s.verificacion_expira_at, s.creado_por, s.nombre
    into v_estado, v_expira, v_creado_por, v_nombre
  from public.salas s
  where s.id = p_sala;

  if v_estado is null then
    raise exception 'La sala no existe';
  end if;

  -- Ya estaba completa: respuesta idempotente.
  if v_estado = 'completa' then
    select count(*) into v_listos
    from public.participantes_sala
    where sala_id = p_sala and verificado_at is not null;
    return v_listos;
  end if;

  if v_estado <> 'pendiente' then
    raise exception 'No hay una verificación pendiente';
  end if;

  if v_expira is not null and v_expira < now() then
    update public.salas
    set verificacion_estado = 'inactiva', verificacion_expira_at = null
    where id = p_sala and verificacion_estado = 'pendiente';
    raise exception 'La verificación expiró. Pide una nueva.';
  end if;

  if not exists (
    select 1 from public.participantes_sala where sala_id = p_sala and user_id = v_uid
  ) then
    raise exception 'No perteneces a esta sala';
  end if;

  -- Permite escribir `verificado_at` aunque la sala esté en fase de picks.
  perform set_config('app.picks_operacion', 'on', true);

  update public.participantes_sala
  set verificado_at = now()
  where sala_id = p_sala and user_id = v_uid and verificado_at is null;

  select count(*) into v_socios
  from public.participantes_sala
  where sala_id = p_sala;

  select count(*) into v_listos
  from public.participantes_sala
  where sala_id = p_sala and verificado_at is not null;

  if v_listos >= v_socios then
    update public.salas
    set verificacion_estado = 'completa', verificacion_expira_at = null
    where id = p_sala and verificacion_estado = 'pendiente';

    if v_creado_por is not null then
      insert into public.notificaciones (user_id, tipo, mensaje)
      values (
        v_creado_por,
        'verificacion_completa',
        'Todos los jugadores de la sala "' || v_nombre || '" confirmaron que están listos.'
      );
    end if;
  end if;

  return v_listos;
end;
$function$
CREATE OR REPLACE FUNCTION public.admin_cancelar_verificacion(p_sala uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.es_admin() then
    raise exception 'Solo administradores';
  end if;

  -- Permite limpiar las marcas aunque la sala esté en fase de picks.
  perform set_config('app.picks_operacion', 'on', true);

  update public.participantes_sala
  set verificado_at = null
  where sala_id = p_sala;

  update public.salas
  set verificacion_estado = 'inactiva',
      verificacion_iniciada_at = null,
      verificacion_expira_at = null
  where id = p_sala;
end;
$function$
CREATE OR REPLACE FUNCTION public.notificar_sala_terminada(p_sala uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_nombre text;
  v_avisados int;
begin
  -- Solo el admin o el servidor (service_role) pueden avisar el fin de partida.
  if not (public.es_admin() or auth.role() = 'service_role') then
    raise exception 'Solo administradores';
  end if;

  select nombre into v_nombre
  from public.salas
  where id = p_sala;

  if v_nombre is null then
    raise exception 'La sala no existe';
  end if;

  insert into public.notificaciones (user_id, tipo, mensaje)
  select ps.user_id,
         'partida_finalizada',
         'La partida de la sala "' || v_nombre || '" terminó. Se repartieron los premios.'
  from public.participantes_sala ps
  where ps.sala_id = p_sala;

  get diagnostics v_avisados = row_count;
  return v_avisados;
end;
$function$
CREATE OR REPLACE FUNCTION public.qa_cleanup()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_ids uuid[];
  v_salas uuid[];
  v_perfiles int;
  v_salas_n int;
  v_auth int;
begin
  select coalesce(array_agg(id), '{}') into v_ids from public.profiles where nick like 'qa-%';
  select coalesce(array_agg(id), '{}') into v_salas from public.salas
    where nombre like 'QA %' or creado_por = any(v_ids);
  v_salas_n := coalesce(array_length(v_salas, 1), 0);

  delete from public.peticiones_dinero where user_id = any(v_ids); delete from public.apuestas_sala where sala_id = any(v_salas)
    or creador_id = any(v_ids) or aceptante_id = any(v_ids);
  alter table public.movimientos_billetera disable trigger user;
  delete from public.movimientos_billetera where user_id = any(v_ids) or creado_por = any(v_ids);
  alter table public.movimientos_billetera enable trigger user;
  delete from public.notificaciones where user_id = any(v_ids);
  delete from public.recargas where user_id = any(v_ids);
  delete from public.retiros where user_id = any(v_ids);
  delete from public.mensajes_chat where user_id = any(v_ids) or sala_id = any(v_salas);
  update public.salas set picks_estado = 'inactivo'
    where id = any(v_salas) and picks_estado = 'en_curso';
  alter table public.participantes_sala disable trigger user;
  delete from public.participantes_sala where user_id = any(v_ids) or sala_id = any(v_salas);
  alter table public.participantes_sala enable trigger user;
  delete from public.lobbies where sala_id = any(v_salas);
  delete from public.partidas where sala_id = any(v_salas);
  delete from public.salas where id = any(v_salas);
  delete from public.profiles where id = any(v_ids);
  get diagnostics v_perfiles = row_count;
  delete from auth.users where id = any(v_ids);
  get diagnostics v_auth = row_count;
  return jsonb_build_object('perfiles', v_perfiles, 'salas', v_salas_n, 'auth', v_auth);
end;
$function$
CREATE OR REPLACE FUNCTION public.donar_saldo(p_receptor uuid, p_monto integer, p_mensaje text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_donante uuid := auth.uid();
  v_saldo integer;
  v_donacion uuid;
  v_mensaje text;
begin
  if v_donante is null then
    raise exception 'Debes iniciar sesión';
  end if;

  if p_receptor is null or p_monto is null then
    raise exception 'Datos incompletos';
  end if;

  if p_monto <= 0 then
    raise exception 'El monto debe ser mayor a S/ 0.00';
  end if;

  if p_receptor = v_donante then
    raise exception 'No puedes donarte saldo a ti mismo';
  end if;

  if not exists (select 1 from public.profiles where id = p_receptor) then
    raise exception 'El usuario no existe';
  end if;

  if exists (select 1 from public.profiles where id = p_receptor and baneado) then
    raise exception 'No puedes donar a una cuenta baneada';
  end if;

  if exists (select 1 from public.profiles where id = v_donante and baneado) then
    raise exception 'Tu cuenta está baneada';
  end if;

  v_mensaje := nullif(btrim(coalesce(p_mensaje, '')), '');

  -- Bloquea la fila del donante: dos donaciones simultáneas del mismo usuario
  -- no pueden gastar dos veces el mismo saldo.
  perform 1 from public.profiles where id = v_donante for update;

  v_saldo := public._saldo_de(v_donante);

  if v_saldo < p_monto then
    raise exception 'Saldo insuficiente: tienes % y quieres donar %',
      format('S/ %s', (v_saldo / 100.0)::numeric(12, 2)),
      format('S/ %s', (p_monto / 100.0)::numeric(12, 2));
  end if;

  insert into public.donaciones (donante_id, receptor_id, monto, mensaje)
  values (v_donante, p_receptor, p_monto, v_mensaje)
  returning id into v_donacion;

  insert into public.movimientos_billetera
    (user_id, tipo, monto, referencia_id, descripcion, creado_por)
  values
    (v_donante, 'donacion_enviada', -p_monto, v_donacion, 'Donación enviada', v_donante);

  insert into public.movimientos_billetera
    (user_id, tipo, monto, referencia_id, descripcion, creado_por)
  values
    (p_receptor, 'donacion_recibida', p_monto, v_donacion, 'Donación recibida', v_donante);

  insert into public.actividades (tipo, emisor_id, receptor_id, monto, descripcion)
  values ('donacion', v_donante, p_receptor, p_monto, v_mensaje);

  insert into public.notificaciones (user_id, tipo, mensaje)
  values (
    p_receptor,
    'donacion_recibida',
    'Recibiste una donación de ' || format('S/ %s', (p_monto / 100.0)::numeric(12, 2)) || '.'
  );

  return public._saldo_de(v_donante);
end;
$function$
CREATE OR REPLACE FUNCTION public.admin_aplicar_multa(p_user uuid, p_monto integer, p_motivo text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_motivo text;
begin
  if not public.es_admin() then
    raise exception 'Solo administradores';
  end if;

  if p_user is null or p_monto is null then
    raise exception 'Datos incompletos';
  end if;

  if p_monto <= 0 then
    raise exception 'El monto debe ser mayor a S/ 0.00';
  end if;

  if p_user = auth.uid() then
    raise exception 'No puedes multar tu propia cuenta';
  end if;

  v_motivo := btrim(coalesce(p_motivo, ''));

  if v_motivo = '' then
    raise exception 'Escribe el motivo de la multa';
  end if;

  -- El movimiento del saldo lo hace `ajuste_admin` (mismo control de saldo,
  -- tipo de movimiento y auditoría que usa el resto del sistema).
  perform public.ajuste_admin(p_user, -p_monto, 'Multa: ' || v_motivo);

  insert into public.actividades (tipo, emisor_id, receptor_id, monto, descripcion)
  values ('multa', auth.uid(), p_user, p_monto, v_motivo);

  insert into public.notificaciones (user_id, tipo, mensaje)
  values (
    p_user,
    'multa',
    'Se aplicó una multa de ' || format('S/ %s', (p_monto / 100.0)::numeric(12, 2)) ||
      '. Motivo: ' || v_motivo
  );
end;
$function$
CREATE OR REPLACE FUNCTION public.sortear_1v1(p_sala uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s public.salas%rowtype;
  v_total int;
  v_ids uuid[];
  v_ganador uuid;
begin
  select * into s from public.salas where id = p_sala for update;
  if not found then return; end if;
  if s.cupo <> 2 then return; end if;
  if s.estado not in ('abierta', 'llena') then return; end if;
  if s.picks_estado <> 'inactivo' then return; end if;

  -- Si los equipos ya están asignados no se vuelve a sortear.
  if exists (
    select 1 from public.participantes_sala
    where sala_id = p_sala and equipo is not null
  ) then
    return;
  end if;

  -- La moneda espera a que ambos confirmen "Estoy listo".
  if s.verificacion_estado = 'pendiente' then return; end if;

  select count(*), array_agg(user_id order by created_at)
    into v_total, v_ids
  from public.participantes_sala
  where sala_id = p_sala;

  if v_total <> 2 then return; end if;

  v_ganador := v_ids[case when random() < 0.5 then 1 else 2 end];

  update public.salas
  set picks_estado = 'eleccion',
      pick_capitan1 = v_ids[1],
      pick_capitan2 = v_ids[2],
      pick_ganador_moneda = v_ganador,
      pick_decision_user_id = v_ganador,
      pick_decision_tipo = 'lado',
      pick_primer_user_id = null,
      pick_turno_user_id = null,
      pick_turno_expira_at = null
  where id = p_sala;
end;
$function$
CREATE OR REPLACE FUNCTION public.iniciar_sorteo_1v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sala_id uuid;
  s public.salas%rowtype;
  v_total int;
begin
  if TG_OP = 'DELETE' then
    v_sala_id := old.sala_id;
  else
    v_sala_id := new.sala_id;
  end if;

  select * into s from public.salas where id = v_sala_id for update;
  if not found then
    if TG_OP = 'DELETE' then return old; else return new; end if;
  end if;

  -- Solo aplica a salas 1v1
  if s.cupo <> 2 then
    if TG_OP = 'DELETE' then return old; else return new; end if;
  end if;

  select count(*) into v_total
  from public.participantes_sala
  where sala_id = v_sala_id;

  if v_total = 2 then
    -- No sorts while the verification is pending: the coin waits for "I'm ready".
    perform public.sortear_1v1(v_sala_id);
  elsif v_total < 2 then
    -- Si alguien sale antes de decidir, se limpia el sorteo para el próximo que entre
    if s.picks_estado <> 'inactivo' and s.estado <> 'en_juego' then
      perform set_config('app.picks_operacion', 'on', true);

      update public.salas
      set picks_estado = 'inactivo',
          pick_capitan1 = null,
          pick_capitan2 = null,
          pick_ganador_moneda = null,
          pick_decision_user_id = null,
          pick_decision_tipo = null,
          pick_primer_user_id = null,
          pick_turno_user_id = null,
          pick_turno_expira_at = null
      where id = v_sala_id;

      update public.participantes_sala
      set equipo = null, es_capitan = false, pick_orden = null
      where sala_id = v_sala_id;
    end if;
  end if;

  if TG_OP = 'DELETE' then return old; else return new; end if;
end;
$function$
CREATE OR REPLACE FUNCTION public.sorteo_1v1_al_completar()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.verificacion_estado is distinct from 'completa' then return new; end if;
  if old.verificacion_estado is not distinct from 'completa' then return new; end if;

  perform public.sortear_1v1(new.id);
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.proteger_resultado_apostado()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if exists (select 1 from public.apuestas_sala where sala_id = old.sala_id and estado = 'liquidada') then
    if tg_op = 'DELETE' then raise exception 'No se puede borrar un resultado con apuestas pagadas'; end if;
    if new.equipo_ganador is distinct from old.equipo_ganador or new.sala_id is distinct from old.sala_id then
      raise exception 'No se puede cambiar un resultado con apuestas pagadas';
    end if;
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.elegir_preferencia_equipo(p_sala uuid, p_equipo integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null then
    raise exception 'Debes iniciar sesión';
  end if;

  if p_equipo is not null and p_equipo not in (1, 2) then
    raise exception 'Lado inválido';
  end if;

  if not exists (
    select 1 from public.participantes_sala
    where sala_id = p_sala and user_id = auth.uid()
  ) then
    raise exception 'No perteneces a esta sala';
  end if;

  -- Solo existe durante la fase en la que los capitanes eligen jugadores.
  if not exists (
    select 1 from public.salas
    where id = p_sala and picks_estado in ('eleccion', 'en_curso')
  ) then
    raise exception 'Solo se puede elegir lado durante la fase de picks';
  end if;

  -- El trigger `bloquear_cambios_en_picks` congela a los participantes durante
  -- los picks: marcamos la operación para poder escribir la preferencia.
  perform set_config('app.picks_operacion', 'on', true);

  update public.participantes_sala
  set preferencia_equipo = p_equipo
  where sala_id = p_sala and user_id = auth.uid();
end;
$function$
CREATE OR REPLACE FUNCTION public.salir_de_sala_con_multa(p_sala uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s public.salas%rowtype; multa integer:=0;
begin
 select * into s from public.salas where id=p_sala for update;
 if s.cupo=10 and s.estado='llena' then multa:=least(200,greatest(0,public._saldo_de(auth.uid())+s.cuota)); end if;
 perform public.salir_de_sala(p_sala);
 return multa;
end $function$
CREATE OR REPLACE FUNCTION public.elegir_radiant_o_lastpick(p_sala uuid, p_opcion text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s public.salas%rowtype;
  v_uid uuid := auth.uid();
  v_cap1 uuid;
  v_cap2 uuid;
  v_rival uuid;
  v_radiant uuid;
  v_dire uuid;
begin
  if v_uid is null then
    raise exception 'Debes iniciar sesión';
  end if;

  if p_opcion is null or p_opcion not in ('radiant', 'lastpick') then
    raise exception 'Opción inválida: usa radiant o lastpick';
  end if;

  select * into s from public.salas where id = p_sala for update;
  if not found then
    raise exception 'La sala no existe';
  end if;

  if s.cupo <> 10 then
    raise exception 'Esta decisión es solo para salas 5v5';
  end if;

  if s.picks_estado <> 'eleccion' then
    raise exception 'La moneda no está esperando una decisión';
  end if;

  if s.pick_decision_user_id is distinct from v_uid then
    raise exception 'Solo el ganador de la moneda puede decidir';
  end if;

  v_cap1 := s.pick_capitan1;
  v_cap2 := s.pick_capitan2;

  if v_cap1 is null or v_cap2 is null then
    raise exception 'Faltan los capitanes';
  end if;

  v_rival := case when v_cap1 = v_uid then v_cap2 else v_cap1 end;

  if p_opcion = 'radiant' then
    -- El ganador toma Radiant y abre el draft.
    v_radiant := v_uid;
    v_dire := v_rival;
  else
    -- Last pick: el ganador toma Dire; el rival se queda Radiant y abre.
    v_radiant := v_rival;
    v_dire := v_uid;
  end if;

  -- La fase de picks congela `participantes_sala`; esto abre la excepción.
  perform set_config('app.picks_operacion', 'on', true);

  update public.participantes_sala
  set equipo = 1
  where sala_id = p_sala and user_id = v_radiant;

  update public.participantes_sala
  set equipo = 2
  where sala_id = p_sala and user_id = v_dire;

  update public.salas
  set picks_estado = 'en_curso',
      pick_decision_user_id = null,
      pick_decision_tipo = null,
      -- Quien abre el draft es siempre el capitán de Radiant.
      pick_primer_user_id = v_radiant,
      pick_turno_user_id = v_radiant,
      pick_turno_expira_at = now() + interval '60 seconds'
  where id = p_sala;
end;
$function$
CREATE OR REPLACE FUNCTION public.siguiente_capitan_de_pick(p_primer uuid, p_otro uuid, p_pick integer)
 RETURNS uuid
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  select case
    when p_pick is null or p_pick <= 1 or p_pick >= 8 then p_primer
    when p_pick in (2, 3, 6, 7) then p_otro
    else p_primer
  end;
$function$
CREATE OR REPLACE FUNCTION public.admin_pedir_verificacion(p_sala uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_cupo int;
  v_estado text;
  v_socios int;
begin
  if not public.es_admin() then
    raise exception 'Solo administradores';
  end if;

  select s.cupo, s.estado into v_cupo, v_estado
  from public.salas s
  where s.id = p_sala
  for update;

  if v_cupo is null then
    raise exception 'La sala no existe';
  end if;

  if v_estado in ('terminada', 'cancelada') then
    raise exception 'La sala ya terminó';
  end if;

  select count(*) into v_socios
  from public.participantes_sala
  where sala_id = p_sala;

  -- Se puede pedir con la sala incompleta: solo hace falta alguien a quien avisar.
  if v_socios = 0 then
    raise exception 'La sala todavía no tiene jugadores';
  end if;

  -- El trigger `bloquear_cambios_en_picks` congela a los participantes durante
  -- la fase de picks. La verificación solo escribe `verificado_at`, así que
  -- se marca la operación para poder pedir la confirmación en cualquier fase.
  perform set_config('app.picks_operacion', 'on', true);

  update public.participantes_sala
  set verificado_at = null
  where sala_id = p_sala;

  update public.salas
  set verificacion_estado = 'pendiente',
      verificacion_iniciada_at = now(),
      verificacion_expira_at = now() + interval '15 minutes'
  where id = p_sala;

  return v_socios;
end;
$function$
CREATE OR REPLACE FUNCTION public.limitar_turno_pick()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.pick_turno_expira_at is not null
     and new.pick_turno_expira_at > now() + interval '45 seconds' then
    new.pick_turno_expira_at := now() + interval '45 seconds';
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.iniciar_verificacion_llenada()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_cupo int;
  v_estado text;
  v_verificacion text;
  v_total int;
begin
  if TG_OP <> 'INSERT' then return new; end if;

  select s.cupo, s.estado, s.verificacion_estado
    into v_cupo, v_estado, v_verificacion
  from public.salas s
  where s.id = new.sala_id;

  if v_cupo is null then return new; end if;
  if v_estado in ('terminada', 'cancelada') then return new; end if;

  -- Ya se estaba pidiendo: no se reinicia (no se pierden las confirmaciones).
  if v_verificacion = 'pendiente' then return new; end if;

  -- Se había completado y entra alguien nuevo: vuelve a pedirse sin borrar a
  -- los que ya confirmaron; el recién llegado ve el aviso y confirma.
  if v_verificacion = 'completa' then
    update public.salas
    set verificacion_estado = 'pendiente',
        verificacion_expira_at = now() + interval '15 minutes'
    where id = new.sala_id;
    return new;
  end if;

  select count(*) into v_total
  from public.participantes_sala
  where sala_id = new.sala_id;

  if v_total < v_cupo then return new; end if;

  update public.salas
  set verificacion_estado = 'pendiente',
      verificacion_iniciada_at = now(),
      verificacion_expira_at = now() + interval '15 minutes'
  where id = new.sala_id;

  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.sincronizar_capitanes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  -- El trigger de la fase de picks congela los cambios de participantes: esta
  -- sincronización es interna y debe poder escribir.
  perform set_config('app.picks_operacion', 'on', true);

  update public.participantes_sala ps
  set es_capitan = coalesce(
        ps.user_id = new.pick_capitan1 or ps.user_id = new.pick_capitan2,
        false
      )
  where ps.sala_id = new.id
    and ps.es_capitan is distinct from coalesce(
          ps.user_id = new.pick_capitan1 or ps.user_id = new.pick_capitan2,
          false
        );

  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.pickear_jugador(p_sala uuid, p_user uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s public.salas%rowtype;
  v_equipo_capitan int;
  v_equipo_objetivo int;
  v_hechos int;
  v_otro uuid;
  v_siguiente uuid;
  v_orden int;
begin
  if auth.uid() is null then raise exception 'No autenticado'; end if;

  select * into s from public.salas where id = p_sala for update;
  if not found then raise exception 'La sala no existe'; end if;
  if s.picks_estado <> 'en_curso' then raise exception 'La fase de picks no está activa'; end if;
  if s.pick_turno_user_id is distinct from auth.uid() then raise exception 'No es tu turno de pickear'; end if;
  if p_user = auth.uid() then raise exception 'No puedes pickearte a ti mismo'; end if;
  if s.pick_primer_user_id is null then raise exception 'Falta el primer pick del sorteo'; end if;

  select equipo into v_equipo_objetivo
  from public.participantes_sala
  where sala_id = p_sala and user_id = p_user;

  if not found then raise exception 'Ese jugador no está en la sala'; end if;
  if v_equipo_objetivo is not null then raise exception 'Ese jugador ya fue elegido'; end if;

  select equipo into v_equipo_capitan
  from public.participantes_sala
  where sala_id = p_sala and user_id = s.pick_turno_user_id;

  if v_equipo_capitan is null then raise exception 'El capitán no tiene equipo asignado'; end if;

  perform set_config('app.picks_operacion', 'on', true);

  select coalesce(max(pick_orden), 0) + 1 into v_orden
  from public.participantes_sala
  where sala_id = p_sala and pick_orden is not null;

  update public.participantes_sala
  set equipo = v_equipo_capitan, pick_orden = v_orden
  where sala_id = p_sala and user_id = p_user;

  -- Solo cuentan los jugadores elegidos: los dos capitanes ya estaban en su equipo.
  select count(*) into v_hechos
  from public.participantes_sala
  where sala_id = p_sala
    and equipo is not null
    and user_id is distinct from s.pick_capitan1
    and user_id is distinct from s.pick_capitan2;

  if v_hechos >= 8 then
    update public.salas
    set picks_estado = 'terminado',
        pick_turno_user_id = null,
        pick_turno_expira_at = null
    where id = p_sala;
  else
    v_otro := case
      when s.pick_primer_user_id = s.pick_capitan1 then s.pick_capitan2
      else s.pick_capitan1
    end;
    v_siguiente := public.siguiente_capitan_de_pick(s.pick_primer_user_id, v_otro, v_hechos + 1);
    update public.salas
    set pick_turno_user_id = v_siguiente,
        pick_turno_expira_at = now() + interval '45 seconds'
    where id = p_sala;
  end if;
end;
$function$
CREATE OR REPLACE FUNCTION public.auto_pickear_si_vencido(p_sala uuid, p_forzar boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s public.salas%rowtype;
  v_equipo_capitan int;
  v_otro uuid;
  v_siguiente uuid;
  v_hechos int;
  v_orden int;
  v_target uuid;
begin
  if auth.uid() is null then raise exception 'Debes iniciar sesión'; end if;

  select * into s from public.salas where id = p_sala for update;
  if not found then raise exception 'La sala no existe'; end if;
  if s.picks_estado <> 'en_curso' then raise exception 'La fase de picks no está activa'; end if;

  if p_forzar then
    if not public.es_admin() then raise exception 'Solo administradores pueden forzar el auto-pick'; end if;
  elsif s.pick_turno_expira_at is null or now() < s.pick_turno_expira_at then
    raise exception 'El turno aún no vence';
  end if;

  select equipo into v_equipo_capitan
  from public.participantes_sala
  where sala_id = p_sala and user_id = s.pick_turno_user_id;

  if v_equipo_capitan is null then raise exception 'El capitán no tiene equipo asignado'; end if;

  -- Elige al disponible con más MMR (desempate: el que entró antes).
  select ps.user_id into v_target
  from public.participantes_sala ps
  left join public.profiles pr on pr.id = ps.user_id
  where ps.sala_id = p_sala
    and ps.equipo is null
    and ps.user_id is distinct from s.pick_capitan1
    and ps.user_id is distinct from s.pick_capitan2
  order by coalesce(pr.mmr, 0) desc, ps.created_at asc
  limit 1;

  if v_target is null then
    update public.salas
    set picks_estado = 'terminado',
        pick_turno_user_id = null,
        pick_turno_expira_at = null
    where id = p_sala;
    return;
  end if;

  perform set_config('app.picks_operacion', 'on', true);

  select coalesce(max(pick_orden), 0) + 1 into v_orden
  from public.participantes_sala
  where sala_id = p_sala and pick_orden is not null;

  update public.participantes_sala
  set equipo = v_equipo_capitan, pick_orden = v_orden
  where sala_id = p_sala and user_id = v_target;

  select count(*) into v_hechos
  from public.participantes_sala
  where sala_id = p_sala
    and equipo is not null
    and user_id is distinct from s.pick_capitan1
    and user_id is distinct from s.pick_capitan2;

  if v_hechos >= 8 then
    update public.salas
    set picks_estado = 'terminado',
        pick_turno_user_id = null,
        pick_turno_expira_at = null
    where id = p_sala;
  else
    v_otro := case
      when s.pick_primer_user_id = s.pick_capitan1 then s.pick_capitan2
      else s.pick_capitan1
    end;
    v_siguiente := public.siguiente_capitan_de_pick(s.pick_primer_user_id, v_otro, v_hechos + 1);
    update public.salas
    set pick_turno_user_id = v_siguiente,
        pick_turno_expira_at = now() + interval '45 seconds'
    where id = p_sala;
  end if;
end;
$function$
CREATE OR REPLACE FUNCTION public.validar_debito_billetera()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.monto < 0 then
    perform 1 from public.profiles where id = new.user_id for update;
    if public._saldo_de(new.user_id)::bigint + new.monto::bigint < 0 then
      raise exception 'Saldo insuficiente para realizar la operación';
    end if;
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.resolver_apuestas_sala(p_sala uuid, p_equipo integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  a public.apuestas_sala%rowtype;
  v_ganador uuid;
begin
  if p_equipo is not null and p_equipo not in (1, 2) then raise exception 'Resultado inválido'; end if;
  perform 1 from public.salas where id = p_sala for update;
  for a in select * from public.apuestas_sala
    where sala_id = p_sala and estado in ('pendiente', 'aceptada') order by id for update
  loop
    if a.estado = 'pendiente' then
      update public.apuestas_sala set estado = 'expirada', resuelto_en = now() where id = a.id;
    elsif p_equipo is null then
      insert into public.movimientos_billetera(user_id, tipo, monto, referencia_id, descripcion, creado_por) values
        (a.creador_id, 'apuesta_reembolso', 550, a.id, 'Apuesta reembolsada: sala cancelada', auth.uid()),
        (a.aceptante_id, 'apuesta_reembolso', 550, a.id, 'Apuesta reembolsada: sala cancelada', auth.uid());
      update public.apuestas_sala set estado = 'reembolsada', resuelto_en = now() where id = a.id;
    else
      v_ganador := case when a.equipo_creador = p_equipo then a.creador_id else a.aceptante_id end;
      insert into public.movimientos_billetera(user_id, tipo, monto, referencia_id, descripcion, creado_por)
        values (v_ganador, 'apuesta_premio', 1000, a.id, 'Premio de apuesta: ' || case when p_equipo = 1 then 'Radiant' else 'Dire' end, auth.uid());
      update public.apuestas_sala set estado = 'liquidada', ganador_id = v_ganador, comision = 100, resuelto_en = now() where id = a.id;
    end if;
    if a.estado = 'aceptada' then
      insert into public.notificaciones(user_id, tipo, mensaje)
        select id, 'apuesta_resultado', 'Apuesta en "' || (select nombre from public.salas where id = p_sala) || '": ' ||
          case when p_equipo is null then 'sala cancelada, recibiste S/ 5.50 de reembolso.'
            when id = v_ganador then 'ganaste, recibiste S/ 10.00.' else 'perdiste tu aporte de S/ 5.50.' end
        from public.profiles where id in (a.creador_id, a.aceptante_id);
    end if;
  end loop;
end;
$function$
CREATE OR REPLACE FUNCTION public.apuestas_resultado_trg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.resolver_apuestas_sala(new.sala_id, new.equipo_ganador);
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.apuestas_estado_sala_trg()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_equipo integer;
begin
  if new.estado = 'cancelada' and old.estado is distinct from 'cancelada' then
    perform public.resolver_apuestas_sala(new.id, null);
  elsif new.estado = 'terminada' and old.estado is distinct from 'terminada' then
    select equipo_ganador into v_equipo from public.partidas where sala_id = new.id;
    if found then
      perform public.resolver_apuestas_sala(new.id, v_equipo);
    else
      -- Algunos cierres actualizan la sala antes de insertar el resultado.
      -- Las aceptadas se pagan con el trigger de partidas, en esa transacción.
      update public.apuestas_sala set estado = 'expirada', resuelto_en = now()
        where sala_id = new.id and estado = 'pendiente';
    end if;
  end if;
  return new;
end;
$function$
CREATE OR REPLACE FUNCTION public.aceptar_apuesta_sala(p_apuesta uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid();
  v_sala uuid;
  v_estado text;
  a public.apuestas_sala%rowtype;
begin
  if v_user is null then raise exception 'Debes iniciar sesión'; end if;
  select sala_id into v_sala from public.apuestas_sala where id = p_apuesta;
  if not found then raise exception 'La apuesta no existe'; end if;
  -- Mismo orden en creación, aceptación, cancelación y cierre: sala → apuesta → perfiles.
  select estado into v_estado from public.salas where id = v_sala for update;
  select * into a from public.apuestas_sala where id = p_apuesta for update;
  if a.aceptante_id = v_user and a.estado in ('aceptada', 'liquidada', 'reembolsada') then return; end if;
  if a.creador_id = v_user then raise exception 'No puedes aceptar tu propia apuesta'; end if;
  if v_estado <> 'en_juego' or exists (select 1 from public.partidas where sala_id = v_sala) then
    raise exception 'La partida ya no admite apuestas';
  end if;
  if a.estado <> 'pendiente' then raise exception 'Esta oferta ya no está disponible'; end if;
  -- Orden estable para aceptar simultáneamente apuestas cruzadas en distintas salas.
  perform id from public.profiles where id in (a.creador_id, v_user) order by id for update;
  if not exists (select 1 from public.profiles where id = v_user and not coalesce(baneado, false))
     or exists (select 1 from public.profiles where id = a.creador_id and baneado) then
    raise exception 'Una de las cuentas no puede apostar';
  end if;
  if public._saldo_de(v_user) < 550 then raise exception 'Necesitas S/ 5.50 de saldo'; end if;
  if public._saldo_de(a.creador_id) < 550 then raise exception 'El creador ya no tiene saldo suficiente'; end if;
  insert into public.movimientos_billetera(user_id, tipo, monto, referencia_id, descripcion, creado_por) values
    (a.creador_id, 'apuesta_aporte', -550, a.id, 'Apuesta: ' || case when a.equipo_creador = 1 then 'Radiant' else 'Dire' end, v_user),
    (v_user, 'apuesta_aporte', -550, a.id, 'Apuesta: ' || case when a.equipo_creador = 1 then 'Dire' else 'Radiant' end, v_user);
  update public.apuestas_sala set aceptante_id = v_user, estado = 'aceptada', aceptado_en = now() where id = a.id;
  insert into public.notificaciones(user_id, tipo, mensaje)
    select id, 'apuesta_aceptada', 'Apuesta confirmada en "' || (select nombre from public.salas where id = v_sala) || '": aportaste S/ 5.50 a ' ||
      case when (id = a.creador_id and a.equipo_creador = 1) or (id = v_user and a.equipo_creador = 2) then 'Radiant' else 'Dire' end || '. Premio total: S/ 10.00.'
    from public.profiles where id in (a.creador_id, v_user);
end;
$function$
CREATE OR REPLACE FUNCTION public.cancelar_apuesta_sala(p_apuesta uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_sala uuid;
  a public.apuestas_sala%rowtype;
begin
  if auth.uid() is null then raise exception 'Debes iniciar sesión'; end if;
  select sala_id into v_sala from public.apuestas_sala where id = p_apuesta;
  if not found then raise exception 'La apuesta no existe'; end if;
  perform 1 from public.salas where id = v_sala for update;
  select * into a from public.apuestas_sala where id = p_apuesta for update;
  if a.creador_id <> auth.uid() then raise exception 'Solo puedes cancelar tus propias ofertas'; end if;
  if a.estado = 'cancelada' then return; end if;
  if a.estado <> 'pendiente' then raise exception 'Solo puedes cancelar ofertas sin aceptar'; end if;
  update public.apuestas_sala set estado = 'cancelada', resuelto_en = now() where id = a.id;
end;
$function$
CREATE OR REPLACE FUNCTION public.ganancias_apuestas_casa()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.es_admin() then raise exception 'Solo administradores'; end if;
  return (select coalesce(sum(comision), 0) from public.apuestas_sala where estado = 'liquidada');
end;
$function$
CREATE OR REPLACE FUNCTION public.crear_apuesta_sala(p_sala uuid, p_equipo integer, p_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_user uuid := auth.uid();
  v_estado text;
  v_anterior public.apuestas_sala%rowtype;
begin
  if v_user is null then raise exception 'Debes iniciar sesión'; end if;
  if p_id is null or p_sala is null or p_equipo is null or p_equipo not in (1, 2) then
    raise exception 'Selecciona Radiant o Dire';
  end if;
  select estado into v_estado from public.salas where id = p_sala for update;
  if not found then raise exception 'La sala no existe'; end if;
  select * into v_anterior from public.apuestas_sala where id = p_id;
  if found then
    if v_anterior.creador_id = v_user and v_anterior.sala_id = p_sala and v_anterior.equipo_creador = p_equipo then
      return p_id;
    end if;
    raise exception 'Identificador de apuesta inválido';
  end if;
  if v_estado <> 'en_juego' or exists (select 1 from public.partidas where sala_id = p_sala) then
    raise exception 'Las apuestas solo están disponibles durante la partida';
  end if;
  perform 1 from public.profiles where id = v_user and not coalesce(baneado, false) for update;
  if not found then raise exception 'Tu cuenta no puede apostar'; end if;
  if public._saldo_de(v_user) < 550 then raise exception 'Necesitas S/ 5.50 de saldo'; end if;
  insert into public.apuestas_sala(id, sala_id, creador_id, equipo_creador)
    values (p_id, p_sala, v_user, p_equipo);
  return p_id;
end;
$function$
CREATE OR REPLACE FUNCTION public.validar_ventana_apuesta()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s public.salas%rowtype;
begin
 if (tg_op='INSERT' and new.estado='pendiente') or (tg_op='UPDATE' and new.estado='aceptada' and old.estado='pendiente') then
  select * into s from public.salas where id=new.sala_id for update;
  if s.estado<>'en_juego' or s.iniciada_at is null or clock_timestamp() >= s.iniciada_at + interval '25 minutes'
     or exists(select 1 from public.partidas where sala_id=s.id) then
   raise exception 'Apuestas cerradas: solo se admiten durante los primeros 25 minutos de la partida';
  end if;
  if exists(select 1 from public.participantes_sala where sala_id=s.id and user_id in (new.creador_id,new.aceptante_id)) then
   raise exception 'Los jugadores de esta partida no pueden apostar en su propia sala';
  end if;
 end if;
 return new;
end $function$
CREATE OR REPLACE FUNCTION public.admin_configurar_cierre(p_sala uuid, p_auto boolean, p_match bigint DEFAULT NULL::bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
 if not public.es_admin() then raise exception 'Solo administradores'; end if;
 if p_match is not null and p_match<=0 then raise exception 'ID de partida inválido'; end if;
 update public.salas set auto_cierre=p_auto,dota_match_id_esperado=p_match where id=p_sala and estado='en_juego';
 if not found then raise exception 'La sala no está en juego'; end if;
end $function$
CREATE OR REPLACE FUNCTION public.salir_de_sala(p_sala uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s public.salas%rowtype; u uuid:=auth.uid(); multa integer:=0;
begin
 if u is null then raise exception 'No autenticado'; end if;
 select * into s from public.salas where id=p_sala for update;
 if not found then raise exception 'La sala no existe'; end if;
 if s.estado not in ('abierta','llena') then raise exception 'No puedes salir de esta sala ahora'; end if;
 perform 1 from public.profiles where id=u for update;
 delete from public.participantes_sala where sala_id=p_sala and user_id=u;
 if not found then raise exception 'No estás en esta sala'; end if;
 insert into public.movimientos_billetera(user_id,tipo,monto,referencia_id,descripcion)
 values(u,'reembolso',s.cuota,s.id,'Salida de sala '||s.nombre);
 if s.cupo=10 and s.estado='llena' then
  multa:=least(200,greatest(0,public._saldo_de(u)));
  if multa>0 then
   insert into public.movimientos_billetera(user_id,tipo,monto,referencia_id,descripcion,creado_por)
   values(u,'ajuste_admin',-multa,s.id,'Multa: abandonó una sala 5v5 llena',u);
   insert into public.actividades(tipo,emisor_id,receptor_id,monto,descripcion)
   values('multa',u,u,multa,'Abandonó una sala 5v5 llena');
   insert into public.notificaciones(user_id,tipo,mensaje)
   values(u,'multa','Multa por abandonar una sala 5v5 llena: S/ '||(multa/100.0)::numeric(12,2));
  end if;
 end if;
 if s.estado='llena' then update public.salas set estado='abierta' where id=s.id; end if;
end $function$
