CREATE OR REPLACE FUNCTION public.cerrar_partida_auto(p_sala uuid, p_dota_match_id bigint, p_equipo_ganador integer, p_duracion integer, p_radiant_score integer, p_dire_score integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s public.salas%rowtype;
  v_admin uuid;
begin
  if auth.role() <> 'service_role' then
    raise exception 'No autorizado';
  end if;

  select * into s from public.salas where id = p_sala for update;
  if not found then raise exception 'La sala no existe'; end if;
  if s.estado <> 'en_juego' then raise exception 'La sala no está en juego'; end if;
  if not s.auto_cierre or s.dota_match_id_esperado is distinct from p_dota_match_id then raise exception 'Cierre automático desactivado o partida no asociada'; end if; if exists (select 1 from public.partidas where sala_id = p_sala) then
    raise exception 'La partida ya fue cerrada';
  end if;

  -- Reutiliza el cierre oficial con contexto de admin.
  select id into v_admin
  from public.profiles
  where rol = 'admin' and coalesce(baneado, false) = false
  order by (id = s.creado_por) desc
  limit 1;

  if v_admin is null then
    raise exception 'No hay un administrador disponible para cerrar la partida';
  end if;

  perform set_config('request.jwt.claim.sub', v_admin::text, true);
  perform set_config('request.jwt.claim.role', 'authenticated', true);
  perform set_config(
    'request.jwt.claims',
    json_build_object('sub', v_admin, 'role', 'authenticated')::text,
    true
  );

  perform public.cerrar_partida_con_detalle(
    p_sala,
    p_dota_match_id,
    p_equipo_ganador,
    p_duracion,
    p_radiant_score,
    p_dire_score,
    true
  );
end;
$function$
CREATE OR REPLACE FUNCTION public.procesar_plazos_arena()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s record; administrador uuid;
begin
 -- Bloqueo compartido con aceptar/crear: primero sala y después sus apuestas.
 for s in select id from public.salas where estado='en_juego' and iniciada_at<=clock_timestamp()-interval '25 minutes' order by id for update skip locked loop
  update public.apuestas_sala set estado='expirada',resuelto_en=clock_timestamp() where sala_id=s.id and estado='pendiente';
 end loop;
 for s in select id,creado_por from public.salas where picks_estado='en_curso' and pick_turno_expira_at<=clock_timestamp() order by id for update skip locked loop
  select id into administrador from public.profiles where rol='admin' and not baneado order by (id=s.creado_por) desc limit 1;
  if administrador is not null then
   perform set_config('request.jwt.claim.sub',administrador::text,true);
   perform set_config('request.jwt.claims',json_build_object('sub',administrador,'role','authenticated')::text,true);
   begin perform public.auto_pickear_si_vencido(s.id,false);
   exception when others then raise warning 'No se pudo ejecutar el auto-pick de sala %: %',s.id,sqlerrm;
   end;
  end if;
 end loop;
end $function$
